import{c as t,Q as a,j as s,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Password policy","description":"How passwords are hashed, minimum length, and forced reset on first login.","frontmatter":{"title":"Password policy","description":"How passwords are hashed, minimum length, and forced reset on first login."},"headers":[],"relativePath":"security/password-policy.md","filePath":"security/password-policy.md"}'),o={name:"security/password-policy.md"};function i(n,e,d,h,c,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h2 id="hashing-algorithm" tabindex="-1">Hashing algorithm <a class="header-anchor" href="#hashing-algorithm" aria-label="Permalink to &quot;Hashing algorithm&quot;">​</a></h2><p>GateKeeper uses <strong>argon2id</strong> for all password hashing. Argon2id is the winner of the Password Hashing Competition and is recommended by OWASP for new applications.</p><p>The specific parameters used:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th></tr></thead><tbody><tr><td>Memory</td><td>64 MB</td></tr><tr><td>Iterations</td><td>3</td></tr><tr><td>Parallelism</td><td>4</td></tr><tr><td>Output length</td><td>32 bytes</td></tr><tr><td>Salt length</td><td>16 bytes (random per hash)</td></tr></tbody></table><p>These match the OWASP recommended minimum for argon2id. They mean each password verification takes roughly 100-200ms on typical hardware, which is slow enough to make brute-force attacks impractical.</p><p>A new random salt is generated for every hash, so two users with the same password have different hashes in the database.</p><h2 id="minimum-length" tabindex="-1">Minimum length <a class="header-anchor" href="#minimum-length" aria-label="Permalink to &quot;Minimum length&quot;">​</a></h2><p>Passwords must be at least <strong>12 characters</strong>. This is enforced server-side on every code path that sets or verifies a password. There is no maximum length.</p><p>There is no complexity requirement (uppercase, numbers, symbols). Length is a better predictor of password strength than complexity rules, and complexity requirements tend to produce patterns like <code>Password1!</code> that are predictable.</p><h2 id="forced-password-change" tabindex="-1">Forced password change <a class="header-anchor" href="#forced-password-change" aria-label="Permalink to &quot;Forced password change&quot;">​</a></h2><p>When an admin creates a user or directly sets a password, the <code>force_password_change</code> flag is set. The user is redirected to <code>/profile/password</code> before they can access anything else, and they cannot skip this step.</p><p>After the user sets their own password, the flag is cleared.</p><h2 id="reset-token-security" tabindex="-1">Reset token security <a class="header-anchor" href="#reset-token-security" aria-label="Permalink to &quot;Reset token security&quot;">​</a></h2><p>Password reset tokens are 32 bytes of cryptographically random data. GateKeeper stores the argon2id hash of the token, not the token itself. The hash uses a fixed salt (<code>gatekeeper-reset-token-salt-v1xx</code>) applied to the raw random bytes. Tokens expire in 30 minutes and are single-use.</p>',14)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
